UICamera = {}
--HD_PATCH_ENABLED = true
function UICamera:GetCameraInfo(id)
	if not UI_CAMERA_ID[id] then
		return 0, 0, 0, 0, 0
	end

	return unpack(UI_CAMERA_ID[id])
end

function UICamera:GetInventoryTypeCameraID(invType, subType)
	local sex = C_Player:GetSex()
	local _, raceID = C_Player:GetRace()
	invType = _G[invType] or invType
	subType = ITEM_SUBCLASS_TO_MASK[subType or ""]
	if subType then
		local id = UI_INVTYPE_CAMERA[invType] and UI_INVTYPE_CAMERA[invType][subType]
		if id then
			return id
		end
	end
	return UI_INVTYPE_CAMERA[invType] and UI_INVTYPE_CAMERA[invType][1] or UI_INVTYPE_CAMERA[raceID] and UI_INVTYPE_CAMERA[raceID][sex] and UI_INVTYPE_CAMERA[raceID][sex][invType] or 0
end

